const items = $input.all();
const clientData = $('Code: Merge Deal Data').first().json;

// Extract text from each Claude response
const getSection = (nodeOutput) => {
  try {
    const content = nodeOutput.json.content[0].text;
    return content;
  } catch(e) {
    return '<p>Section content unavailable.</p>';
  }
};

const sec1 = $('Claude: Section 1 — Welcome Letter').first().json.content[0].text;
const sec2 = $('Claude: Section 2 — Credentials Guide').first().json.content[0].text;
const sec3 = $('Claude: Section 3 — What We\'re Building').first().json.content[0].text;
const sec4 = $('Claude: Section 4 — Project Timeline').first().json.content[0].text;
const sec5 = $('Claude: Section 5 — How to Work With IntraWeb').first().json.content[0].text;
const sec6 = $('Claude: Section 6 — Billing & Payment Terms').first().json.content[0].text;
const sec7 = $('Claude: Section 7 — FAQ').first().json.content[0].text;

const html = `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>IntraWeb Technologies — ${clientData.company_name} Onboarding Package</title>
  <style>
    * { box-sizing: border-box; margin: 0; padding: 0; }
    body { font-family: 'Georgia', serif; color: #1a1a1a; background: #fff; font-size: 14px; line-height: 1.7; }
    .header { background: #0a0a0a; color: #fff; padding: 40px 60px; border-bottom: 4px solid #3b82f6; }
    .header h1 { font-size: 28px; font-weight: 700; letter-spacing: -0.5px; }
    .header p { color: #9ca3af; margin-top: 6px; font-size: 14px; }
    .toc { background: #f8fafc; padding: 40px 60px; border-bottom: 1px solid #e5e7eb; }
    .toc h2 { font-size: 18px; font-weight: 700; margin-bottom: 16px; color: #0a0a0a; }
    .toc ol { padding-left: 20px; }
    .toc li { margin-bottom: 8px; color: #3b82f6; font-size: 13px; }
    .section { padding: 50px 60px; border-bottom: 1px solid #e5e7eb; }
    .section h2 { font-size: 22px; font-weight: 700; color: #0a0a0a; margin-bottom: 24px; padding-bottom: 12px; border-bottom: 2px solid #3b82f6; }
    .section h3 { font-size: 16px; font-weight: 700; color: #374151; margin: 20px 0 10px; }
    .section p { margin-bottom: 14px; color: #374151; }
    .section ul, .section ol { padding-left: 20px; margin-bottom: 14px; }
    .section li { margin-bottom: 6px; color: #374151; }
    .section table { width: 100%; border-collapse: collapse; margin: 20px 0; }
    .section th { background: #0a0a0a; color: #fff; padding: 10px 14px; text-align: left; font-size: 12px; text-transform: uppercase; letter-spacing: 0.5px; }
    .section td { padding: 10px 14px; border-bottom: 1px solid #e5e7eb; }
    .section tr:nth-child(even) td { background: #f9fafb; }
    .section strong { color: #0a0a0a; }
    .badge { display: inline-block; background: #3b82f6; color: #fff; font-size: 11px; font-weight: 700; padding: 3px 10px; border-radius: 20px; text-transform: uppercase; letter-spacing: 0.5px; margin-bottom: 10px; }
    .footer { background: #0a0a0a; color: #9ca3af; padding: 30px 60px; text-align: center; font-size: 12px; }
    .footer strong { color: #fff; }
  </style>
</head>
<body>
  <div class="header">
    <h1>IntraWeb Technologies</h1>
    <p>Client Onboarding Package &nbsp;|&nbsp; ${clientData.company_name} &nbsp;|&nbsp; ${clientData.tier} Tier &nbsp;|&nbsp; ${clientData.start_date}</p>
  </div>
  <div class="toc">
