      <li>Credentials &amp; Access Intake Guide</li>
      <li>What We're Building For You</li>
      <li>Project Timeline</li>
      <li>How to Work With IntraWeb</li>
      <li>Billing &amp; Payment Terms</li>
      <li>Frequently Asked Questions</li>
    </ol>
  </div>
  <div class="section">
    <span class="badge">Section 1</span>
    <h2>Welcome Letter</h2>
    ${sec1}
  </div>
  <div class="section">
    <span class="badge">Section 2</span>
    <h2>Credentials &amp; Access Intake Guide</h2>
    ${sec2}
  </div>
  <div class="section">
    <span class="badge">Section 3</span>
    <h2>What We're Building For You</h2>
    ${sec3}
  </div>
  <div class="section">
    <span class="badge">Section 4</span>
    <h2>Project Timeline</h2>
    ${sec4}
  </div>
  <div class="section">
    <span class="badge">Section 5</span>
    <h2>How to Work With IntraWeb</h2>
    ${sec5}
  </div>
  <div class="section">
    <span class="badge">Section 6</span>
    <h2>Billing &amp; Payment Terms</h2>
    ${sec6}
  </div>
  <div class="section">
    <span class="badge">Section 7</span>
    <h2>Frequently Asked Questions</h2>
    ${sec7}
  </div>
  <div class="footer">
    <strong>IntraWeb Technologies LLC</strong> &nbsp;|&nbsp; john@intrawebtech.com &nbsp;|&nbsp; Generated ${new Date().toLocaleDateString('en-US', { year: 'numeric', month: 'long', day: 'numeric' })}
  </div>
</body>
</html>`;

return [{
  json: {
    html,
    client_name: clientData.client_name,
    company_name: clientData.company_name,
    tier: clientData.tier,
    deal_id: clientData.deal_id,
    owner_email: clientData.owner_email,
    owner_phone: clientData.owner_phone,
    filename: `IntraWeb — ${clientData.company_name} — Onboarding Package.pdf`
  }
}];

const { html, filename, client_name, company_name, tier, deal_id, owner_email, owner_phone } = $input.first().json;

let pdfBase64;
try {
  const puppeteer = require('puppeteer');
  const browser = await puppeteer.launch({ args: ['--no-sandbox', '--disable-setuid-sandbox'] });
  const page = await browser.newPage();
  await page.setContent(html, { waitUntil: 'networkidle0' });
  const pdf = await page.pdf({
    format: 'A4',
    margin: { top: '0.75in', right: '0in', bottom: '0.75in', left: '0in' },
    printBackground: true
  });
  await browser.close();
  pdfBase64 = pdf.toString('base64');
} catch(e) {
  // Fallback: return HTML as base64 if Puppeteer unavailable
  pdfBase64 = Buffer.from(html).toString('base64');
}

return [{
  json: {
    pdf: pdfBase64,
    filename,
    client_name,
    company_name,
    tier,
    deal_id,
    owner_email,
    owner_phone
  }
}];

const driveResponse = $input.first().json;
const pdfData = $('Code: Generate PDF via Puppeteer').first().json;
const fileId = driveResponse.id || '';
const driveLink = `https://drive.google.com/file/d/${fileId}/view`;
return [{
  json: {
    file_id: fileId,
    drive_link: driveLink,
    pdf: pdfData.pdf,
    filename: pdfData.filename,
    client_name: pdfData.client_name,
    company_name: pdfData.company_name,
    tier: pdfData.tier,
    deal_id: pdfData.deal_id,
    owner_email: pdfData.owner_email,
    owner_phone: pdfData.owner_phone
  }
}];

