const response = $input.first().json;
const results = response.results || [];
const driveData = $('Code: Extract Drive Link').first().json;
if (results.length === 0) {
  return [{ json: { email_opened: false, ...driveData } }];
}
const props = results[0].properties;
const openDate = props.hs_email_open_date ? new Date(props.hs_email_open_date) : null;
const twentyFourHoursAgo = new Date(Date.now() - 24 * 60 * 60 * 1000);
const emailOpened = openDate && openDate > twentyFourHoursAgo;
return [{ json: { email_opened: emailOpened, ...driveData } }];

